// ══════════════════════════════════════════════════
//  Node 2: Verify Invitation Code
// ══════════════════════════════════════════════════

const body = $input.first().json.body || $input.first().json;
const submittedCode = (body.verificationCode || '').trim().toUpperCase();

let expectedCode = 'SCVA-2026';
try {
  const varCode = $vars.SCVA_VERIFICATION_CODE;
  if (varCode && String(varCode).trim()) {
    expectedCode = String(varCode).trim().toUpperCase();
  }
} catch (e) {}

if (!submittedCode) {
  throw new Error('MISSING_CODE: رمز التحقق مطلوب');
}

if (submittedCode !== expectedCode) {
  throw new Error('INVALID_VERIFICATION_CODE: رمز التحقق غير صحيح');
}

return [{ json: body }];

// ══════════════════════════════════════════════════
//  Node 3: Format & Validate Data
// ══════════════════════════════════════════════════

const d = $input.first().json;

const required = ['firstName', 'lastName', 'fullName', 'englishName'];
for (const f of required) {
  if (!d[f] || !String(d[f]).trim()) {
    throw new Error(`MISSING_REQUIRED: الحقل المطلوب غير موجود: ${f}`);
  }
}

const clean = (v) => (v ? String(v).trim() : '');

const language = clean(d.language) || 'ar';
const submittedAt = d.submittedAt || new Date().toISOString();

const genderMap = {
  ar: { male: 'ذكر', female: 'أنثى' },
  en: { male: 'Male', female: 'Female' },
};
const specialtyMap = {
  ar: { cardiology: 'قلبية داخلية', cardiac_surgery: 'جراحة قلب' },
  en: { cardiology: 'Cardiology', cardiac_surgery: 'Cardiac Surgery' },
};
const membershipMap = {
  ar: { original: 'عضو أصيل', associate: 'عضو مشارك' },
  en: { original: 'Original Member', associate: 'Associate Member' },
};

const gender = genderMap[language]?.[d.gender] || clean(d.gender);
const specialty = specialtyMap[language]?.[d.specialty] || clean(d.specialty);
const membershipType = membershipMap[language]?.[d.membershipType] || clean(d.membershipType);

return [{
  json: {
    language,
    verificationCode: clean(d.verificationCode),
    firstName:    clean(d.firstName),
    lastName:     clean(d.lastName),
    fullName:     clean(d.fullName),
    fatherName:   clean(d.fatherName),
    englishName:  clean(d.englishName),
    birthDate:    clean(d.birthDate),
    gender:       gender,
    genderRaw:    clean(d.gender),
    specialty:    specialty,
    specialtyRaw: clean(d.specialty),
    membershipType: membershipType,
    membershipTypeRaw: clean(d.membershipType),
    email:        clean(d.email),
    phone:        clean(d.phone),
    city:         clean(d.city),
    workAddress:  clean(d.workAddress),
    joinDate:     clean(d.joinDate),
    escId:        clean(d.escId),
    submittedAt,
  }
}];

// ══════════════════════════════════════════════════
//  Build Email HTML — v2.2 (AI-enhanced + locale-safe date)
// ══════════════════════════════════════════════════

const d = $input.first().json;
const v = (val) => (val && String(val).trim()) ? String(val).trim() : '—';
const isAr = d.language !== 'en';

// دالة تنسيق التاريخ بدون اعتماد على Locale (يحل مشكلة ar-SY في بيئة n8n)
function fmtDate(iso) {
  try {
    const dt = new Date(iso);
    if (isNaN(dt.getTime())) return iso || '—';
    const pad = n => String(n).padStart(2, '0');
    return pad(dt.getDate()) + '/' + pad(dt.getMonth() + 1) + '/' + dt.getFullYear()
         + '  ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
  } catch (e) { return iso || '—'; }
}

const submittedFmt = fmtDate(d.submittedAt || new Date().toISOString());
const aiAnalysis   = d.aiAnalysis || '';
const aiWelcome    = d.aiWelcome  || '';

// ── كتلة تحليل AI للمسؤول ─────────────────────────────────────────────────
const aiBlock = aiAnalysis
  ? '<div style="background:#fefce8;border:1px solid #fde047;border-radius:8px;padding:14px 18px;margin-bottom:22px;font-size:13px;color:#713f12;line-height:1.8"><strong style="font-size:12px;display:block;margin-bottom:6px;color:#a16207">🤖 تحليل الذكاء الاصطناعي</strong>' + aiAnalysis + '</div>'
  : '';

// ── Admin Email HTML ────────────────────────────────────────────────────────
const adminHtml = `<!DOCTYPE html>
<html dir="rtl" lang="ar"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<style>
body{font-family:Segoe UI,Arial,sans-serif;background:#f0f4f8;margin:0;padding:20px;color:#1a202c;direction:rtl}
.card{max-width:640px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.10)}
.hdr{background:linear-gradient(135deg,#0f2027,#203a43,#2c5364);color:#fff;padding:32px;text-align:center}
.hdr h1{margin:0 0 6px;font-size:18px;font-weight:700}.hdr p{margin:0;font-size:12px;opacity:.78}
.badge{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;padding:4px 14px;font-size:11px;margin-top:10px}
.body{padding:28px 32px}
.alert-new{background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:13px;color:#166534}
.sec{margin-bottom:22px}
.sec-title{font-size:11px;font-weight:700;color:#06b6d4;letter-spacing:.6px;text-transform:uppercase;border-bottom:1.5px solid #e2e8f0;padding-bottom:5px;margin-bottom:10px}
table{width:100%;border-collapse:collapse}tr:nth-child(even) td{background:#f8fafc}
td{padding:8px 10px;font-size:13px;vertical-align:top;border-bottom:1px solid #f1f5f9}
td.lbl{width:36%;color:#64748b;font-weight:600;white-space:nowrap}td.val{color:#1e293b;font-weight:500}
.ftr{background:#f8fafc;padding:18px 32px;text-align:center;border-top:1px solid #e2e8f0}
.ftr-org{font-size:13px;font-weight:700;color:#0f172a;margin-bottom:3px}.ftr-sub{font-size:11px;color:#94a3b8}
</style></head><body><div class="card">
<div class="hdr"><div style="font-size:38px;margin-bottom:10px">🔔</div>
<h1>إشعار تسجيل عضو جديد</h1>
<p>الرابطة السورية لأمراض وجراحة القلب</p>
<span class="badge">${isAr ? 'نموذج عربي' : 'English Form'}</span></div>
<div class="body">
<div class="alert-new">✅ تم استلام طلب عضوية جديد بنجاح عبر النموذج الإلكتروني.</div>
${aiBlock}
<div class="sec"><div class="sec-title">البيانات الشخصية</div><table>
<tr><td class="lbl">الاسم الأول</td><td class="val">${v(d.firstName)}</td></tr>
<tr><td class="lbl">الكنية</td><td class="val">${v(d.lastName)}</td></tr>
<tr><td class="lbl">الاسم الكامل (عربي)</td><td class="val">${v(d.fullName)}</td></tr>
<tr><td class="lbl">الاسم الكامل (إنجليزي)</td><td class="val">${v(d.englishName)}</td></tr>
<tr><td class="lbl">اسم الأب</td><td class="val">${v(d.fatherName)}</td></tr>
<tr><td class="lbl">تاريخ الميلاد</td><td class="val">${v(d.birthDate)}</td></tr>
<tr><td class="lbl">الجنس</td><td class="val">${v(d.gender)}</td></tr>
</table></div>
<div class="sec"><div class="sec-title">البيانات المهنية</div><table>
<tr><td class="lbl">التخصص</td><td class="val">${v(d.specialty)}</td></tr>
<tr><td class="lbl">نوع العضوية</td><td class="val">${v(d.membershipType)}</td></tr>
<tr><td class="lbl">تاريخ الانضمام</td><td class="val">${v(d.joinDate)}</td></tr>
<tr><td class="lbl">ESC ID</td><td class="val">${v(d.escId)}</td></tr>
</table></div>
<div class="sec"><div class="sec-title">بيانات التواصل</div><table>
<tr><td class="lbl">البريد الإلكتروني</td><td class="val">${v(d.email)}</td></tr>
<tr><td class="lbl">رقم الهاتف</td><td class="val">${v(d.phone)}</td></tr>
<tr><td class="lbl">المدينة</td><td class="val">${v(d.city)}</td></tr>
<tr><td class="lbl">عنوان العمل</td><td class="val">${v(d.workAddress)}</td></tr>
</table></div>
<div class="sec"><div class="sec-title">معلومات الطلب</div><table>
<tr><td class="lbl">لغة النموذج</td><td class="val">${isAr ? 'العربية' : 'English'}</td></tr>
<tr><td class="lbl">وقت الإرسال</td><td class="val">${submittedFmt}</td></tr>
</table></div>
</div><div class="ftr">
<div class="ftr-org">الرابطة السورية لأمراض وجراحة القلب</div>
<div class="ftr-sub">Syrian Cardiovascular Association — SCVA</div>
</div></div></body></html>`;

// ── Member Confirmation Email ───────────────────────────────────────────────
const dir      = isAr ? 'rtl' : 'ltr';
const lang     = d.language || 'ar';
const nameVal  = isAr ? v(d.fullName) : v(d.englishName);
const greeting = isAr ? ('عزيزي/عزيزتي الدكتور/ة ' + v(d.fullName)) : ('Dear Dr. ' + v(d.englishName));
const title    = isAr ? 'تم استلام طلب العضوية' : 'Membership Application Received';
const orgName  = isAr ? 'الرابطة السورية لأمراض وجراحة القلب' : 'Syrian Cardiovascular Association — SCVA';

const aiWelcomeBlock = aiWelcome
  ? '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:14px 18px;margin-bottom:20px;font-size:14px;color:#166534;line-height:1.8">' + aiWelcome + '</div>'
  : '';

const defaultMsg = isAr
  ? 'يسعدنا إخبارك بأنه تم استلام طلب انضمامك إلى الرابطة السورية لأمراض وجراحة القلب بنجاح. سيقوم فريقنا المختص بمراجعة طلبك والتواصل معك قريباً.'
  : 'We are pleased to confirm that your membership application to the Syrian Cardiovascular Association (SCVA) has been received. Our team will review your application and contact you soon.';

const stepsTitle = isAr ? 'الخطوات القادمة' : 'Next Steps';
const steps = isAr
  ? ['مراجعة طلبك من قِبل لجنة القبول', 'التواصل معك للتحقق من المعلومات إذا لزم', 'إشعارك بقرار القبول النهائي']
  : ['Review by the admission committee', 'Contact you to verify information if needed', 'Notify you of the final admission decision'];
const stepsHtml = steps.map(s => '<li>' + s + '</li>').join('');

const memberHtml = `<!DOCTYPE html>
<html dir="${dir}" lang="${lang}"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<style>
body{font-family:Segoe UI,Arial,sans-serif;background:#f0f4f8;margin:0;padding:20px;color:#1a202c}
.card{max-width:640px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.10)}
.hdr{background:linear-gradient(135deg,#0f2027,#203a43,#2c5364);color:#fff;padding:32px;text-align:center}
.hdr h1{margin:0 0 6px;font-size:18px;font-weight:700}.hdr p{margin:0;font-size:12px;opacity:.78}
.body{padding:28px 32px}
.greeting{font-size:15px;font-weight:600;margin-bottom:14px;color:#0f172a}
.msg{font-size:13px;line-height:1.85;color:#475569;margin-bottom:20px}
.sec{margin-bottom:22px}
.sec-title{font-size:11px;font-weight:700;color:#06b6d4;letter-spacing:.6px;text-transform:uppercase;border-bottom:1.5px solid #e2e8f0;padding-bottom:5px;margin-bottom:10px}
table{width:100%;border-collapse:collapse}tr:nth-child(even) td{background:#f8fafc}
td{padding:8px 10px;font-size:13px;vertical-align:top;border-bottom:1px solid #f1f5f9}
td.lbl{width:40%;color:#64748b;font-weight:600}td.val{color:#1e293b;font-weight:500}
.steps{background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px 20px;margin-bottom:22px}
.steps h4{margin:0 0 10px;font-size:13px;font-weight:700;color:#1d4ed8}
.steps ol{margin:0;padding-inline-start:20px}
.steps li{font-size:13px;color:#374151;margin-bottom:6px;line-height:1.6}
.ftr{background:#f8fafc;padding:18px 32px;text-align:center;border-top:1px solid #e2e8f0}
.ftr-org{font-size:13px;font-weight:700;color:#0f172a;margin-bottom:3px}.ftr-sub{font-size:11px;color:#94a3b8}
</style></head><body><div class="card">
<div class="hdr"><div style="font-size:38px;margin-bottom:10px">✅</div>
<h1>${title}</h1><p>${orgName}</p></div>
<div class="body">
<div class="greeting">${greeting},</div>
${aiWelcomeBlock}
<div class="msg">${defaultMsg}</div>
<div class="sec"><div class="sec-title">${isAr ? 'ملخص طلبك' : 'Application Summary'}</div><table>
<tr><td class="lbl">${isAr ? 'الاسم' : 'Name'}</td><td class="val">${nameVal}</td></tr>
<tr><td class="lbl">${isAr ? 'البريد الإلكتروني' : 'Email'}</td><td class="val">${v(d.email)}</td></tr>
<tr><td class="lbl">${isAr ? 'نوع العضوية' : 'Membership type'}</td><td class="val">${v(d.membershipType)}</td></tr>
<tr><td class="lbl">${isAr ? 'وقت الإرسال' : 'Submitted at'}</td><td class="val">${submittedFmt}</td></tr>
</table></div>
<div class="steps"><h4>${stepsTitle}</h4><ol>${stepsHtml}</ol></div>
</div><div class="ftr">
<div class="ftr-org">الرابطة السورية لأمراض وجراحة القلب</div>
<div class="ftr-sub">Syrian Cardiovascular Association — SCVA</div>
</div></div></body></html>`;

return [{
  json: {
    language: d.language, verificationCode: d.verificationCode,
    firstName: d.firstName, lastName: d.lastName, fullName: d.fullName,
    fatherName: d.fatherName, englishName: d.englishName, birthDate: d.birthDate,
    gender: d.gender, genderRaw: d.genderRaw, specialty: d.specialty,
    specialtyRaw: d.specialtyRaw, membershipType: d.membershipType,
    membershipTypeRaw: d.membershipTypeRaw, email: d.email, phone: d.phone,
    city: d.city, workAddress: d.workAddress, joinDate: d.joinDate,
    escId: d.escId, submittedAt: d.submittedAt,
    adminHtml,
    memberHtml,
    adminSubject: '🔔 عضو جديد: ' + (v(d.fullName) !== '—' ? v(d.fullName) : v(d.englishName)) + ' | الرابطة السورية لأمراض وجراحة القلب',
    memberSubject: isAr
      ? '✅ تم استلام طلب انضمامك | الرابطة السورية لأمراض وجراحة القلب'
      : '✅ Your Membership Application Received | SCVA',
    memberEmail: d.email || '',
  }
}];

// ══════════════════════════════════════════════════
//  AI Analysis Node v2.4 — مُحقَّن من إعدادات SCVA
//  المزود والمفتاح مُضمَّنان تلقائياً عند تحميل ملف Workflow
// ══════════════════════════════════════════════════

const d = $input.first().json;
let aiAnalysis = '';
let aiWelcome  = '';

// ── مُحقَّن تلقائياً من إعدادات التطبيق عند تحميل الـ Workflow ──
const AI_PROVIDER = '__SCVA_AI_PROVIDER__'; // openai | gemini
const AI_API_KEY  = '__SCVA_AI_KEY__';

try {
  const hasKey = AI_API_KEY && AI_API_KEY !== '__SCVA_AI_KEY__' && AI_API_KEY.length > 10;
  const canFetch = typeof fetch === 'function';

  if (hasKey && canFetch) {

    const callAI = async (prompt, maxTokens) => {
      if (AI_PROVIDER === 'gemini') {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-04-17:generateContent?key=${AI_API_KEY}`;
        const resp = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] })
        });
        const json = await resp.json();
        return json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
      } else {
        // OpenAI (default)
        const resp = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${AI_API_KEY}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: [{ role: 'user', content: prompt }],
            max_tokens: maxTokens,
            temperature: 0.7
          })
        });
        const json = await resp.json();
        return json.choices?.[0]?.message?.content?.trim() || '';
      }
    };

    // ── فقرة تحليلية للمسؤول ─────────────────────────────
    const adminPrompt = `أنت مساعد إداري للرابطة السورية لأمراض وجراحة القلب (SCVA).
تلقّت الرابطة طلب عضوية جديدة بالبيانات التالية:
- الاسم: ${d.fullName || '—'} (${d.englishName || '—'})
- التخصص: ${d.specialty || 'غير محدد'}
- نوع العضوية: ${d.membershipType || 'غير محدد'}
- المدينة: ${d.city || 'غير محددة'}
- ESC ID: ${d.escId || 'غير موجود'}
- بريد إلكتروني: ${d.email ? 'موجود ✓' : 'غير موجود ✗'}
- هاتف: ${d.phone ? 'موجود ✓' : 'غير موجود ✗'}

اكتب فقرة احترافية موجزة (3-4 جمل) تتضمن تقييم الطلب وأي بيانات ناقصة وتوصية بالإجراء القادم. اكتب مباشرة دون عنوان.`;

    aiAnalysis = await callAI(adminPrompt, 300);

    // ── رسالة ترحيب للعضو ────────────────────────────────
    const isAr = d.language !== 'en';
    const memberPrompt = isAr
      ? `اكتب جملتين أو ثلاث جمل ترحيبية دافئة واحترافية للدكتور/ة ${d.fullName || ''} المتقدم لعضوية "${d.membershipType || 'العضوية'}" في الرابطة السورية لأمراض وجراحة القلب. اشكره على تقديم طلبه واذكر أن المراجعة ستستغرق وقتاً قصيراً.`
      : `Write 2-3 warm and professional welcome sentences to Dr. ${d.englishName || ''} who applied for "${d.membershipType || 'membership'}" at the Syrian Cardiovascular Association (SCVA). Thank them and mention their application is under review.`;

    aiWelcome = await callAI(memberPrompt, 150);
  }
} catch (_) {
  aiAnalysis = '';
  aiWelcome  = '';
}

return [{ json: { ...d, aiAnalysis, aiWelcome } }];
